// @texture reflectionImage
struct Params {
 reflectedEye: vec3f, // @default 0 Reflected camera position.
 reflectedTarget: vec3f, // @default 0 Reflected camera target.
 reflectedFov: f32, // @default 70 Reflected camera vertical field of view.
 reflectionStrength: f32, // @default 0.75 Wet polished concrete reflectivity.
};
fn cementHash(p: vec2f) -> f32 {
 let cell=vec2i(p);var h=bitcast<u32>(cell.x)*374761393u+bitcast<u32>(cell.y)*668265263u;
 h=(h^(h>>13u))*1274126177u;h=h^(h>>16u);
 return f32(h&16777215u)/16777216.0;
}
fn cementNoise(p: vec2f) -> f32 {
 let i=floor(p);let f=fract(p);let u=f*f*(3.0-2.0*f);
 return mix(mix(cementHash(i),cementHash(i+vec2f(1.0,0.0)),u.x),mix(cementHash(i+vec2f(0.0,1.0)),cementHash(i+vec2f(1.0,1.0)),u.x),u.y);
}
fn reflectedSample(pixel: vec2f) -> vec3f {
 let dims=vec2i(textureDimensions(reflectionImage));
 let pos=pixel-vec2f(0.5);let base=vec2i(floor(pos));let f=fract(pos);
 let a=textureLoad(reflectionImage,clamp(base,vec2i(0),dims-vec2i(1)),0).rgb;
 let b=textureLoad(reflectionImage,clamp(base+vec2i(1,0),vec2i(0),dims-vec2i(1)),0).rgb;
 let c=textureLoad(reflectionImage,clamp(base+vec2i(0,1),vec2i(0),dims-vec2i(1)),0).rgb;
 let d=textureLoad(reflectionImage,clamp(base+vec2i(1,1),vec2i(0),dims-vec2i(1)),0).rgb;
 return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);
}
fn surface(s: SurfaceIn,p: Params) -> SurfaceOut {
 var o=surfaceDefaults(s);
 let x=s.world.xz;
 let cementVariation=cementNoise(x*0.6)*0.65+cementNoise(x*2.1)*0.35;
 let fine=cementNoise(x*52.0);
 let brushingPhase=x.x*145.0+cementNoise(x*1.8)*2.0;
 let brushing=(cementNoise(x*vec2f(1.2,95.0))-0.5)*2.0;
 let grain=(fine-0.5)*0.32+brushing*0.10+(cementVariation-0.5)*0.55;
 let roomFade=exp(-0.006*pow(max(0.0,distance(s.eye,s.world)-12.0),2.0));
 o.albedo=vec4f(vec3f(0.022,0.026,0.034)*(1.0+grain)*roomFade,1.0);
 o.normal=normalize(s.normal+vec3f((fine-0.5)*0.055,0.0,brushing*0.035));
 let forward=normalize(p.reflectedTarget-p.reflectedEye);
 let right=normalize(cross(forward,vec3f(0.0,1.0,0.0)));
 let up=cross(right,forward);
 let relative=s.world-p.reflectedEye;
 let z=dot(relative,forward);
 let halfHeight=tan(p.reflectedFov*0.00872664626);
 let uv=vec2f(0.5+dot(relative,right)/(max(z,0.001)*halfHeight*1.7777778)*0.5,0.5-dot(relative,up)/(max(z,0.001)*halfHeight)*0.5);
 var reflection=vec3f(0.0);
 if(z>0.0 && all(uv>vec2f(0.002)) && all(uv<vec2f(0.998))) {
  let dims=textureDimensions(reflectionImage);
  let ripple=vec2f(cementNoise(x*5.0)-0.5,cementNoise(x*5.0+19.0)-0.5)*1.6;
  let pixel=uv*vec2f(dims)+ripple;
  reflection=reflectedSample(pixel);
 }
 let facing=abs(dot(normalize(s.eye-s.world),normalize(s.normal)));
 let fresnel=0.035+0.965*pow(1.0-facing,5.0);
 let damp=0.60+0.15*cementVariation;
 o.emissive=reflection*fresnel*p.reflectionStrength*damp*roomFade+vec3f(0.003501,0.004102,0.005423)*(1.0-roomFade);
 return o;
}

struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 exposure: f32, // @default 1 Exposure before filmic output.
 focusDistance: f32, // @default 9.7 Camera-space focus distance in scene units.
 aperture: f32, // @default 7.5 Small screen-space circle-of-confusion gain in pixels.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
fn viewDistance(uv: vec2f) -> f32 {
 let dims = textureDimensions(inputTexture1);
 let pixel = clamp(vec2i(uv * vec2f(dims)),vec2i(0),vec2i(dims)-vec2i(1));
 return textureLoad(inputTexture1,pixel,0).r * 90.0;
}
@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let original = textureSampleLevel(inputTexture,inputSampler,uv,0.0);
 let depth = viewDistance(uv);
 let radius = min(2.5,abs(depth-params.focusDistance) / max(depth,1.0) * params.aperture);
 var sum = original.rgb * 2.0;
 var total = 2.0;
 var bloom = vec3f(0.0);
 for (var i=0u;i<12u;i++) {
  let a = f32(i) * 2.39996323;
  let disk = vec2f(cos(a),sin(a)) * sqrt((f32(i)+0.5)/12.0);
  let tap = clamp(uv + disk * radius / frameU.resolution,vec2f(0.0),vec2f(1.0));
  let otherDepth = viewDistance(tap);
  let weight = mix(0.08,1.0,1.0-smoothstep(0.5,2.0,abs(depth-otherDepth)));
  sum += textureSampleLevel(inputTexture,inputSampler,tap,0.0).rgb * weight;
  total += weight;
  let glint = textureSampleLevel(inputTexture,inputSampler,clamp(uv+disk*4.0/frameU.resolution,vec2f(0.0),vec2f(1.0)),0.0).rgb;
  bloom += max(glint-vec3f(0.85),vec3f(0.0));
 }
 let c = sum/total + bloom * (0.028/12.0);
 let p = uv * 2.0-1.0;
 let vignette = 1.0-0.20*smoothstep(0.28,1.7,dot(p,p));
 let airUv = (uv-vec2f(0.20,0.20))*vec2f(1.25,1.8);
 let air = exp(-dot(airUv,airUv)*3.5);
 let beamAxis=0.04+uv.y*0.48;
 let beamWidth=0.055+uv.y*0.16;
 let beam=exp(-pow(abs((uv.x-beamAxis)/beamWidth),2.0))*exp(-uv.y*2.0);
 let visibility=0.2+0.8*smoothstep(9.0,18.0,depth);
 let atmosphere=vec3f(0.009,0.013,0.021)*air+vec3f(0.015,0.023,0.036)*beam*visibility;
 return vec4f(c*vignette*params.exposure + atmosphere,original.a);
}

