struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params { amount: f32, };
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let base = vec3f(0.009,0.009,0.01) + vec3f(0.025,0.026,0.028) * pow(max(0.0, sin(uv.y * 3.141592654)), 2.0);
 let cool = exp(-pow(abs((uv.x - 0.22) / 0.035), 8.0) - pow(abs((uv.y - 0.34) / 0.11), 8.0));
 let warm = exp(-pow(abs((uv.x - 0.73) / 0.045), 8.0) - pow(abs((uv.y - 0.48) / 0.21), 8.0));
 let strip = exp(-pow(abs((uv.y - 0.22) / 0.018), 2.0)) * (0.3 + 0.7 * pow(sin(uv.x * 3.141592654), 2.0));
 let wrapFront = min(abs(uv.x - 0.98), 1.0 - abs(uv.x - 0.98));
 let front = exp(-pow(wrapFront / 0.045, 2.0) - pow(abs((uv.y - 0.61) / 0.15), 2.0));
 let lowBounce = exp(-pow(abs((uv.x - 0.52) / 0.18),4.0) - pow(abs((uv.y - 0.76) / 0.10),4.0));
 let c = front * vec3f(1.4,1.6,2.0) + lowBounce * vec3f(0.55,0.65,0.85) + base + cool * vec3f(0.9,1.6,2.5) + warm * vec3f(2.2,0.95,0.28) + strip * vec3f(0.55,0.75,1.1);
 return vec4f(c * params.amount, 1.0);
}

struct Params {
 striation: f32, // @default 0.055 Machining contrast.
 film: f32, // @default 0.22 Thin film edge strength.
};
fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
 var o = surfaceDefaults(s);
 let v = normalize(s.eye - s.world);
 let fresnel = pow(1.0 - abs(dot(normalize(s.normal), v)), 3.0);
 let machiningPhase = s.uv.y * 240.0 + 0.15 * sin(s.uv.x * 45.0);
 let scratches = sin(machiningPhase) * (1.0 - smoothstep(0.6, 2.6, fwidth(machiningPhase)));
 let finePhase = s.uv.x * 2200.0 + sin(s.uv.y * 53.0);
 let fine = sin(finePhase) * (1.0 - smoothstep(0.6, 2.6, fwidth(finePhase)));
 let grain = scratches * 0.7 + fine * 0.3;
 let phase = s.uv.x * 9.0 + fresnel * 5.4;
 let iridescent = 0.5 + 0.5 * cos(vec3f(0.2, 2.3, 4.4) + phase);
 let edge = pow(abs(cos(s.uv.y * 6.283185307)), 7.0);
 o.albedo = vec4f(vec3f(0.095, 0.055, 0.028) * (1.0 + p.striation * grain) + iridescent * p.film * fresnel * edge, 1.0);
 o.roughness = clamp(0.32 + grain * 0.045 - edge * 0.025, 0.16, 0.38);
 o.metallic = 1.0;
 o.emissive = iridescent * fresnel * edge * 0.014;
 return o;
}

struct Params { glow:f32, // @default 1 Musical colour strength.
};
fn surface(s:SurfaceIn,p:Params)->SurfaceOut {
 var o=surfaceDefaults(s);let n=normalize(s.normal);let v=normalize(s.eye-s.world);let r=reflect(-v,n);let f=pow(1.0-abs(dot(n,v)),2.6);
 let pearl=pow(max(0.0,dot(r,normalize(vec3f(-0.6,0.65,0.65)))),18.0);
 let rim=pow(max(0.0,dot(r,normalize(vec3f(0.7,0.25,-0.45)))),28.0);
 let optical=0.5+0.5*cos(vec3f(0.3,2.4,4.5)+s.uv.x*10.0+f*4.0);
 let veinPhase=s.uv.x*320.0+2.5*sin(s.uv.y*25.1327+s.uv.x*32.0);
 let vein=pow(0.5+0.5*sin(veinPhase),12.0)*(1.0-smoothstep(0.9,3.0,fwidth(veinPhase)));
 o.albedo=vec4f(0.0,0.0,0.0,1.0);
 o.emissive=vec3f(0.70,0.82,0.93)*pearl*(0.23+0.5*f)+vec3f(1.0,0.70,0.38)*rim*0.3+optical*f*0.045 +s.tint.rgb*p.glow*(0.14+0.55*f+0.20*vein);
 return o;
}

struct Params { warmth:f32, // @default 0.2 Inner porcelain warmth.
};
fn surface(s:SurfaceIn,p:Params)->SurfaceOut {var o=surfaceDefaults(s);let f=pow(1.0-abs(dot(normalize(s.normal),normalize(s.eye-s.world))),3.0);let veins=pow(0.5+0.5*sin(s.uv.y*56.0+2.5*sin(s.uv.x*42.0)),9.0);o.albedo=vec4f(mix(vec3f(0.018,0.032,0.040),vec3f(0.15,0.19,0.17),0.35+0.30*veins),1.0);o.roughness=0.18+0.12*veins;o.emissive=s.tint.rgb*(0.10+0.4*f);return o;}

parameters.kernel:
struct Params {
 c0: vec3f, // @default 0 The mixed colour of notes resonating in chamber 1.
 c1: vec3f, // @default 0 The mixed colour of notes resonating in chamber 2.
 c2: vec3f, // @default 0 The mixed colour of notes resonating in chamber 3.
 c3: vec3f, // @default 0 The mixed colour of notes resonating in chamber 4.
 c4: vec3f, // @default 0 The mixed colour of notes resonating in chamber 5.
 c5: vec3f, // @default 0 The mixed colour of notes resonating in chamber 6.
 c6: vec3f, // @default 0 The mixed colour of notes resonating in chamber 7.
 c7: vec3f, // @default 0 The mixed colour of notes resonating in chamber 8.
 c8: vec3f, // @default 0 The mixed colour of notes resonating in chamber 9.
 motion: f32, // @default 1 Strength of the music's mechanical response.
 bloom: f32, // @default 1 Colour radiance, separate from motion.
 tension: f32, // @default 0.3 Eased harmonic tension opens the harp chambers.
 energy: f32, // @default 0.4 Eased musical energy.
 palette: f32, // @default 0 Colour offset in turns.
 a0: f32, // @default 0 Resonance of harp chamber 1.
 a1: f32, // @default 0 Resonance of harp chamber 2.
 a2: f32, // @default 0 Resonance of harp chamber 3.
 a3: f32, // @default 0 Resonance of harp chamber 4.
 a4: f32, // @default 0 Resonance of harp chamber 5.
 a5: f32, // @default 0 Resonance of harp chamber 6.
 a6: f32, // @default 0 Resonance of harp chamber 7.
 a7: f32, // @default 0 Resonance of harp chamber 8.
 a8: f32, // @default 0 Resonance of harp chamber 9.
 shell:f32, // @default 0 Surface offset for the optical coating.
};
// All parts use this same continuous rig. Strings, ribs, pins and capillaries share their anchors.
fn spine(u:f32,t:f32)->vec3f {
 return vec3f(-4.45+9.1*u,2.55+1.62*u+0.43*sin(u*4.9),0.30*sin(u*5.0))
  +vec3f(0.025*sin(t*0.19+u*2.0),0.06*sin(t*0.24-u*2.4),0.05*sin(t*0.16+u*3.0));
}
fn rootU(b:u32)->f32 {let v=array<f32,9>(0.07,0.13,0.27,0.39,0.51,0.64,0.76,0.89,0.32);return v[b];}
fn basePitch(b:u32)->f32 {let v=array<f32,9>(24.0,36.0,48.0,48.0,60.0,60.0,72.0,72.0,36.0);return v[b];}
fn activity(b:u32,p:Params)->f32 {let v=array<f32,9>(p.a0,p.a1,p.a2,p.a3,p.a4,p.a5,p.a6,p.a7,p.a8);return v[b];}
fn dimensions(b:u32)->vec3f {
 let v=array<vec3f,9>(vec3f(4.1,1.04,-0.44),vec3f(2.5,0.83,1.78),vec3f(3.0,0.93,1.03),vec3f(3.2,0.93,-0.67),vec3f(2.9,0.84,1.08),vec3f(3.1,0.93,-0.35),vec3f(2.1,0.66,1.12),vec3f(2.3,0.78,0.19),vec3f(2.1,0.68,2.30));return v[b];
}
fn bankColour(b:u32,p:Params)->vec3f {let c=array<vec3f,9>(p.c0,p.c1,p.c2,p.c3,p.c4,p.c5,p.c6,p.c7,p.c8);return c[b];}
fn hue(note:f32,offset:f32)->vec3f {
 let h=note*0.0833333333+offset;
 return 0.14+0.86*(0.5+0.5*cos(6.2831853*(h+vec3f(0.02,0.69,0.36))));
}
fn rail(b:u32,u:f32,top:bool,t:f32,p:Params)->vec3f {
 let d=dimensions(b);let ph=f32(b)*1.71;
 let breathing=0.035*sin(t*0.28+ph)+p.motion*(0.15*activity(b,p)+0.10*p.tension);
 let angle=d.z+breathing*sin(u*2.4);
 let axis=vec3f(cos(angle),sin(angle),0.0);
 let side=vec3f(-sin(angle),cos(angle),0.0);
 let spread=1.0+p.motion*(0.20*p.tension+0.28*activity(b,p));
 let bow=pow(max(0.0,sin(u*3.14159265)),0.85);
 let skew=1.0+select(0.10,-0.16,top)*sin(u*3.14159+ph);
 let lateral=select(-0.32,1.0,top)*d.y*bow*spread*skew;
 let root=spine(rootU(b),t);
 let zOffsets=array<f32,9>(0.50,-0.30,-0.70,0.65,-0.52,0.35,-0.35,-0.10,-0.95);
 let flex=p.motion*activity(b,p)*0.21*sin(u*3.14159)*sin(t*1.05-u*3.3+ph);
 let depth=sin(u*3.14159265)*(zOffsets[b]+0.19*sin(u*3.7+ph+t*0.16)+flex);
 return root+axis*d.x*u+side*(lateral+0.055*sin(t*0.39+ph-u*2.0)*u)+vec3f(0.0,0.0,depth);
}
fn railFrame(b:u32,u:f32,top:bool,t:f32,p:Params)->mat3x3f {
 let tangent=normalize(rail(b,min(1.001,u+0.001),top,t,p)-rail(b,u,top,t,p));
 let side=normalize(cross(vec3f(0.0,0.0,1.0),tangent));
 return mat3x3f(tangent,side,normalize(cross(tangent,side)));
}
fn stringAnchor(b:u32,s:f32,top:bool,t:f32,p:Params)->vec3f {
 let u=select(0.08+0.84*s,0.13+0.76*s,top);
 let f=railFrame(b,u,top,t,p);
 return rail(b,u,top,t,p)+f[2]*0.042;
}

fn process(p:Point,ctx:PointCtx)->Point {
 var q=p;let col=ctx.index%192u;let row=(ctx.index/192u)%12u;let sheet=ctx.index/2304u;let b=sheet/2u;let top=sheet%2u==0u;let u=f32(col)/191.0;let phi=f32(row)*6.2831853/12.0;
 let f=railFrame(b,u,top,ctx.absTime,ctx.params);let c=rail(b,u,top,ctx.absTime,ctx.params);
 let taper=0.26+0.74*pow(max(0.0,sin(u*3.14159)),0.75);
 let width=(0.080+0.075*pow(sin(u*3.14159),2.0)+0.095*exp(-u*14.0))*taper+ctx.params.shell;
 let thick=0.018*taper+ctx.params.shell*0.35;
 q.position=c+f[1]*cos(phi)*width+f[2]*sin(phi)*thick;
 let e=activity(b,ctx.params);q.tint=vec4f(bankColour(b,ctx.params)*(0.04+1.3*e),1.0);return q;
}
